325	        if (ownerDto == null) {
326	            return;
327	        }
328	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
329	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
330	        owner.setAddress(composeAddress(ownerDto));
331	    }
