333	    /**
334	     * Composes the effective, normalized postal address for an owner from the supplied fields,
335	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
336	     * present, the result is the normalized {@code addressLine1} with the normalized
337	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
338	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
339	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
340	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
341	     */
342	    default String composeAddress(OwnerFieldsDto ownerDto) {
343	        if (ownerDto == null) {
344	            return null;
345	        }
346	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
347	        if (line1 != null && !line1.isEmpty()) {
348	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
349	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
350	        }
351	        return normalizeAddress(ownerDto.getAddress());
352	    }
353	
354	    /**
355	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
356	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
357	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
358	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
359	     * {@code '12 MAIN STREET'}.
