369	    /**
370	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
371	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
372	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
373	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
374	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
375	     *
376	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
377	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
378	     *
379	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
380	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
381	     */
382	    @Named("normalizeTelephone")
383	    default String normalizeTelephone(String telephone) {
384	        return TelephoneNormalizer.toE164(telephone);
385	    }
386	
387	    /**
388	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
389	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
