391	     *
392	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
393	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
394	     * e.g. on update).
395	     */
396	    @Named("normalizeEmail")
397	    default String normalizeEmail(String email) {
398	        return email == null ? null : email.toLowerCase(Locale.ROOT);
399	    }
400	
401	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
402	
403	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
404	
405	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
406	        OwnerPageDto ownerPageDto = new OwnerPageDto();
407	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
408	        ownerPageDto.setPage(ownerPage.getNumber());
409	        ownerPageDto.setSize(ownerPage.getSize());
410	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
411	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
412	        return ownerPageDto;
413	    }
414	}
